INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(68036, 0, 0, 'Thousands of years ... without new playthings ... I will enjoy this.', 14, 0, 100, 0, 0, 35339, 'Durumu - Intro'),
(68036, 1, 0, 'I ... welcome ... the void\'s ... embrace.', 14, 0, 100, 0, 0, 35338, 'Durumu - Aggro'),
(68036, 2, 0, 'I expected so much more. How ... disappointing.', 14, 0, 100, 0, 0, 35337, 'Durumu - Death'),
(68036, 3, 0, 'I expected so much more. How ... disappointing.', 14, 0, 100, 0, 0, 35337, 'Durumu - Berserk'),
(68036, 4, 0, 'Do you see what I did there?', 14, 0, 100, 0, 0, 35340, 'Durumu - Kill 1'),
(68036, 5, 0, 'Looks like you couldn\'t keep up ... pity.', 14, 0, 100, 0, 0, 35341, 'Durumu - Kill 2'),
(68036, 6, 0, 'Watch your footing ... muhahaha!', 14, 0, 100, 0, 0, 35342, 'Durumu - Spell 1'),
(68036, 7, 0, 'The mists hide many secrets ... if you know where to look.', 14, 0, 100, 0, 0, 35343, 'Durumu - Spell 2'),
(68036, 8, 0, 'I\'m keeping an eye on you.', 14, 0, 100, 0, 0, 35344, 'Durumu - Spell 3'),
(68036, 9, 0, 'Observe your demise.', 14, 0, 100, 0, 0, 35345, 'Durumu - Spell 4');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(68065, 0, 0, '|TInterface\\Icons\\trade_archaeology_whitehydrafigurine:20|tMegaera begins to |cFFF00000|Hspell:139458|h[Rampage]|h|r!', 41, 0, 100, 0, 0, 0, ''),
(68065, 1, 0, 'Megaera\'s rage subsides.', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(68078, 0, 0, 'Strike quickly, Manchu. Show them no mercy!', 14, 0, 100, 0, 0, 35474, ''),
(68078, 1, 0, 'All brawn. No brains. A recoverable loss.', 14, 0, 100, 0, 0, 35475, ''),
(68078, 2, 0, 'Focus, Weisheng. Show your enemy the meaning of pain!', 14, 0, 100, 0, 0, 35479, ''),
(68078, 3, 0, 'He fought with honor. His first and last mistake.', 14, 0, 100, 0, 0, 35476, ''),
(68078, 4, 0, 'Stare into the face of true power!', 14, 0, 100, 0, 0, 35465, ''),
(68078, 5, 0, 'How can this be?!', 14, 0, 100, 0, 0, 35462, ''),
(68078, 6, 0, 'Quet\'zal! Unleash the storm upon my enemies!!!', 14, 0, 100, 0, 0, 35467, ''),
(68078, 7, 0, 'Dam\'ren!  Freeze them to oblivion!', 14, 0, 100, 0, 0, 35466, ''),
(68078, 8, 0, 'ARGH! Worthless mongrels! I will kill you myself!', 14, 0, 100, 0, 0, 35477, ''),
(68078, 9, 0, 'More... training...', 14, 0, 100, 0, 0, 35469, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(68397, 0, 0, 'You! You have earned my ire. I will make an example of you, such that all who look upon my might will tremble and submit.', 14, 0, 100, 0, 0, 35589, ''),
(68397, 1, 0, 'I am Lei Shen, slayer of kings and gods. You have made a grave mistake.', 14, 0, 100, 0, 0, 35581, ''),
(68397, 2, 0, 'Submit!', 14, 0, 100, 0, 0, 35601, ''),
(68397, 3, 0, 'You would challenge me in my own sanctum? Witness your folly!', 14, 0, 100, 0, 0, 35595, ''),
(68397, 4, 0, 'Bah! I will crush you myself. Let us see how you fare against Lightning.', 14, 0, 100, 0, 0, 35596, ''),
(68397, 5, 0, 'Lightning, seek my foes!', 14, 0, 100, 0, 0, 35602, ''),
(68397, 6, 0, 'You are NOTHING! I wield the power of the heavens!', 14, 0, 100, 0, 0, 35597, ''),
(68397, 7, 0, 'NO! You are UNWORTHY! I... AM... THE THUNDER KING!', 14, 0, 100, 0, 0, 35598, ''),
(68397, 8, 0, 'I sought only to finish... the work of the Gods...', 14, 0, 100, 0, 0, 35585, ''),
(68397, 9, 0, '|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t%s begins to cast |cFFFF0000|Hspell:135096|h[Thunderstruck]|h|r! Run!', 41, 0, 100, 0, 0, 0, ''),
(68397, 10, 0, '%s is about to end |cFFFF0000Supercharge Conduits|r!', 41, 0, 100, 0, 0, 0, ''),
(68397, 11, 0, '|TInterface\\Icons\\ability_thunderking_lightningwhip.blp:20|t%s begins to cast |cFFFF0000|Hspell:136850|h[Lightning Whip]|h|r!', 41, 0, 100, 0, 0, 0, ''),
(68397, 12, 0, '|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t The |cFFFF0000Northwest|r doors begin to open, causing |cFFFF0000|Hspell:136889|h[Violent Gale Winds]|h|r!', 41, 0, 100, 0, 0, 0, ''),
(68397, 13, 0, '|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t The |cFFFF0000Northeast|r doors begin to open, causing |cFFFF0000|Hspell:136889|h[Violent Gale Winds]|h|r!', 41, 0, 100, 0, 0, 0, ''),
(68397, 14, 0, '|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t The |cFFFF0000Southeast|r doors begin to open, causing |cFFFF0000|Hspell:136889|h[Violent Gale Winds]|h|r!', 41, 0, 100, 0, 0, 0, ''),
(68397, 15, 0, '|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t The |cFFFF0000Southwest|r doors begin to open, causing |cFFFF0000|Hspell:136889|h[Violent Gale Winds]|h|r!', 41, 0, 100, 0, 0, 0, '');
