INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(69702, 0, 0, 'Stop them! The Animus must not be disturbed!', 14, 0, 100, 0, 0, 35725, ''),
(69702, 1, 0, 'The power... It cannot be wielded this way! You tempt forces you do not understand!', 14, 0, 100, 0, 0, 35722, ''),
(69702, 2, 0, 'You have doomed yourselves. It... is... unleashed.', 14, 0, 100, 0, 0, 35724, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(69712, 0, 0, 'The eggs in one of the upper nests begin to hatch!', 41, 0, 100, 0, 0, 0, ''),
(69712, 1, 0, 'The eggs in one of the lower nests begin to hatch!', 41, 0, 100, 0, 0, 0, ''),
(69712, 2, 0, '|TInterface\\Icons\\ability_hunter_pet_dragonhawk.blp:20|tJi-Kun sends her |cFFFF0000|Hspell:134380|h[Quills]|h|r flying in all directions!', 41, 0, 100, 0, 0, 0, ''),
(69712, 3, 0, '|TInterface\\Icons\\ability_druid_galewinds.blp:20|tJi-Kun uses her wings to create a massive |cFFFF0000|Hspell:134370|h[Down Draft]|h|r!', 41, 0, 100, 0, 0, 0, ''),
(69712, 4, 0, '|TInterface\\Icons\\ability_hunter_animalhandler.blp:20|tJi-Kun |cFFFF0000|Hspell:138923|h[Caws]|h|r, sending powerful sound waves at her enemies!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(69756, 0, 0, 'The orb explodes!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70056, 0, 0, 'Des fools thought they beat me once before. Dey only make me stronger. Now we show dem da true power of the Zandalari!', 14, 0, 100, 11, 0, 35404, 'ToT Garajal Intro 1'),
(70056, 1, 0, 'Let me share dis gift with ya!', 14, 0, 100, 11, 0, 35395, 'ToT Garajal Intro 2'),
(70056, 2, 0, 'Da Zandalari cannot be stopped!', 14, 0, 100, 11, 0, 35400, 'ToT Garajal Intro 3'),
(70056, 3, 0, 'Wit de Thunder King\'s power de Zandalari will be reborn!', 14, 0, 100, 11, 0, 35401, 'ToT Garajal Intro 4'),
(70056, 4, 0, 'De Thunder King will reward us for stoppin\' ya!', 14, 0, 100, 11, 0, 35397, 'ToT Garajal Intro End');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70437, 0, 0, 'You have swept the filth from my doorstep. Perhaps you are worthy of my attention.', 14, 0, 100, 0, 0, 35587, 'Lei shen event 1'),
(70437, 1, 0, 'But your trespass ends here. None may enter my forbidden stronghold. I shall rebuild this bridge with your bones for bricks.', 14, 0, 100, 0, 0, 35588, 'Lei Shen event 2');
